package org.sleepwell.app;

import android.content.Context;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.UiDevice;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

/** Real isolated SQLite reference checks, injected grant release; never changes an OS grant. */
public class AlarmToneGrantTest {
    @Test public void discardedUnacceptedGrantsReleaseOnlyNewUnsharedOwnership()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));Map<String,?> before=Prefs.of(c).getAll();String database="sleepwell-verification-"+UUID.randomUUID()+".db",uri="content://inert.tones/owned";android.content.SharedPreferences sounds=c.getSharedPreferences(database+"-sounds",Context.MODE_PRIVATE);Records.Factory pinned=context->new Store(context,database);int[] released={0};AlarmToneImport.GrantRelease fake=(context,value)->{assertEquals(uri,value.toString());released[0]++;};try{try(Store store=pinned.open(c)){store.getWritableDatabase();}AlarmToneImport.Result discarded=new AlarmToneImport.Result(uri,"Fixture",true,fake);discarded.discard(c,pinned,sounds);discarded.discard(c,pinned,sounds);assertEquals(1,released[0]);assertFalse("Expired completion cannot later select a released grant",discarded.accept());AlarmToneImport.Result accepted=new AlarmToneImport.Result(uri,"Fixture",true,fake);assertTrue(accepted.accept());assertFalse(accepted.accept());accepted.discard(c,pinned,sounds);assertEquals(1,released[0]);new AlarmToneImport.Result(uri,"Fixture",false,fake).discard(c,context->{fail("Existing grants must not query or release");return null;},sounds);assertEquals(1,released[0]);try(Store store=pinned.open(c)){Alarm saved=new Alarm(1);saved.tone=uri;store.save(saved);}new AlarmToneImport.Result(uri,"Fixture",true,fake).discard(c,pinned,sounds);assertEquals("Shared alarm grant stays available",1,released[0]);try(Store store=pinned.open(c)){store.deleteAlarm(1);}sounds.edit().putString("mixUri",uri).commit();new AlarmToneImport.Result(uri,"Fixture",true,fake).discard(c,pinned,sounds);assertEquals("Saved sleep-sound grant stays available",1,released[0]);sounds.edit().putInt("mixUri",7).commit();new AlarmToneImport.Result(uri,"Fixture",true,fake).discard(c,pinned,sounds);assertEquals("Uncertain saved mix reference preserves access",1,released[0]);new AlarmToneImport.Result(uri,"Fixture",true,fake).discard(c,context->{throw new IllegalStateException("Synthetic storage unavailable");},sounds);assertEquals("Uncertain references preserve access",1,released[0]);assertEquals(before,Prefs.of(c).getAll());}finally{c.deleteDatabase(database);c.deleteSharedPreferences(database+"-sounds");assertEquals(before,Prefs.of(c).getAll());}}
}
